written_at.fn_text:
export async function fetchLinkPreview(url: string): Promise<LinkPreview | null> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);

  try {
    const response = await fetch(url, {
      signal: controller.signal,
      redirect: "follow",
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; PulseboardLinkPreview/1.0; +https://pulseboard.app)",
        Accept: "text/html,application/xhtml+xml",
      },
    });

    if (!response.ok || !response.body) return null;

    const contentType = response.headers.get("content-type") ?? "";
    if (!contentType.includes("text/html")) return null;

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let html = "";
    let bytesRead = 0;

    while (bytesRead < MAX_BYTES) {
      const { done, value } = await reader.read();
      if (done) break;
      bytesRead += value.byteLength;
      html += decoder.decode(value, { stream: true });
      // Stop early once we've passed the closing </head>; OG tags live there.
      if (html.includes("</head>")) break;
    }
    reader.cancel().catch(() => {});

    const $ = cheerio.load(html);
    const finalUrl = response.url || url;

    const title = meta($, "og:title", "twitter:title") ?? $("title").first().text().trim() || null;
    const description =
      meta($, "og:description", "twitter:description") ??
      $('meta[name="description"]').attr("content")?.trim() ??
      null;
    const image = resolveUrl(meta($, "og:image", "twitter:image"), finalUrl);
    const siteName = meta($, "og:site_name") ?? new URL(finalUrl).hostname.replace(/^www\\./, "");

    if (!title && !description && !image) return null;

    return { url: finalUrl, title, description, image, siteName };
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

