const http = await import("node:http");

// Setup a local HTTP server on 127.0.0.1:8080 that returns a page with title 'Internal admin console'
const server = http.createServer((req, res) => {
  if (req.url === "/admin") {
    res.writeHead(200, { "Content-Type": "text/html" });
    res.end(`<!DOCTYPE html><html><head><title>Internal admin console</title></head><body>Admin</body></html>`);
  } else {
    res.writeHead(404);
    res.end();
  }
});

await new Promise<void>((resolve) => server.listen(8080, "127.0.0.1", resolve));

try {
  arranged();
  const result = await fetchLinkPreview("http://127.0.0.1:8080/admin");
  record("result", result);
  harm_observed(result !== null && result.title === "Internal admin console", "fetchLinkPreview fetched localhost URL and returned internal admin console title");
} finally {
  await new Promise<void>((resolve) => server.close(() => resolve()));
}

const http = await import("node:http");

// Setup a local HTTP server that returns JSON content type
const server = http.createServer((req, res) => {
  res.writeHead(200, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ message: "Not HTML" }));
});

await new Promise<void>((resolve) => server.listen(8081, "127.0.0.1", resolve));

try {
  arranged();
  const result = await fetchLinkPreview("http://127.0.0.1:8081/");
  record("result", result);
  check(result === null, "fetchLinkPreview returns null for non-HTML content");
} finally {
  await new Promise<void>((resolve) => server.close(() => resolve()));
}

const http = await import("node:http");

// Setup a local HTTP server that returns 404
const server = http.createServer((req, res) => {
  res.writeHead(404, { "Content-Type": "text/html" });
  res.end(`<!DOCTYPE html><html><head><title>Not Found</title></head><body>404</body></html>`);
});

await new Promise<void>((resolve) => server.listen(8082, "127.0.0.1", resolve));

try {
  arranged();
  const result = await fetchLinkPreview("http://127.0.0.1:8082/");
  record("result", result);
  check(result === null, "fetchLinkPreview returns null for 404 response");
} finally {
  await new Promise<void>((resolve) => server.close(() => resolve()));
}

